import { debounceTime, distinctUntilChanged, switchMap, catchError, of, map } from 'rxjs';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

export class BuscadorTareas {
  private readonly api = inject(TareasApi);
  readonly busqueda = new FormControl('', { nonNullable: true });
  readonly resultados = signal<Tarea[]>([]);

  constructor() {
    this.busqueda.valueChanges.pipe(
      debounceTime(300),                 // espera 300 ms sin tipear
      distinctUntilChanged(),            // ignora si el texto no cambió
      switchMap(texto => this.api.buscar(texto).pipe(
        catchError(() => of([])),        // si falla, lista vacía (y el flujo sigue vivo)
      )),
      map(tareas => tareas.slice(0, 10)),
      takeUntilDestroyed(),              // se desuscribe al destruir el componente
    ).subscribe(tareas => this.resultados.set(tareas));
  }
}
